package vn.edu.eaut.lab7.model;
public class Sach { private int id; private String maSach,tenSach,tacGia,theLoai; private double gia; public Sach(){} public Sach(int id,String maSach,String tenSach,String tacGia,String theLoai,double gia){this.id=id;this.maSach=maSach;this.tenSach=tenSach;this.tacGia=tacGia;this.theLoai=theLoai;this.gia=gia;} public int getId(){return id;} public void setId(int v){id=v;} public String getMaSach(){return maSach;} public void setMaSach(String v){maSach=v;} public String getTenSach(){return tenSach;} public void setTenSach(String v){tenSach=v;} public String getTacGia(){return tacGia;} public void setTacGia(String v){tacGia=v;} public String getTheLoai(){return theLoai;} public void setTheLoai(String v){theLoai=v;} public double getGia(){return gia;} public void setGia(double v){gia=v;} }